<?php use App\Services\LocationDirectEditPolicy; ?>
<div class="page-heading"><div><div class="breadcrumb-lite">Organization / Location</div><h1><?= e($location['name_en']) ?></h1><p><?= e($location['dad_number']) ?> &middot; <?= e($location['type_name']) ?></p></div><div><?php if(LocationDirectEditPolicy::allowed()): ?><a class="btn btn-primary me-2" href="<?= e(url('locations/'.$location['id'].'/edit')) ?>">Edit</a><?php endif; ?><a class="btn btn-outline-secondary" href="<?= e(url('locations/type/'.$location['type_key'])) ?>">Back to List</a></div></div>
<div class="row g-3"><div class="col-lg-5"><div class="card"><div class="card-body"><h2 class="h5">Location Details</h2><dl class="row mb-0"><dt class="col-5">DAD Number</dt><dd class="col-7"><?= e($location['dad_number']) ?></dd><dt class="col-5">Official Code</dt><dd class="col-7"><?= e($location['official_code']?:'—') ?></dd><?php if($location['type_key']==='GN_DIVISION'): ?><dt class="col-5">GN Code</dt><dd class="col-7"><?= e($location['gn_code']?:'—') ?></dd><dt class="col-5">GN Code for PLR</dt><dd class="col-7"><?= e($location['gn_code_for_plr']?:'—') ?></dd><?php endif; ?><dt class="col-5">Type</dt><dd class="col-7"><?= e($location['type_name']) ?></dd><dt class="col-5">Status</dt><dd class="col-7"><?= e(ucwords(strtolower(str_replace('_',' ',$location['operational_status'])))) ?></dd><dt class="col-5">Approval</dt><dd class="col-7"><?= e(ucwords(strtolower(str_replace('_',' ',$location['approval_status'])))) ?></dd></dl></div></div></div><div class="col-lg-7"><div class="card"><div class="card-body"><h2 class="h5">Location Structure</h2><?php if($gnDsHierarchy!==null): ?><div class="mb-3"><strong>DS Division:</strong> <?php if($gnDsHierarchy['status']==='ASSIGNED'): ?><?= e($gnDsHierarchy['location']['dad_number'].' - '.$gnDsHierarchy['location']['name_en']) ?><?php elseif($gnDsHierarchy['status']==='NOT_ASSIGNED'): ?><span class="text-muted">Not assigned</span><?php else: ?><span class="badge text-bg-warning">Data Issue - Multiple current DS Divisions</span><?php if($gnDsHierarchy['conflicts']!==[]): ?><ul class="small mt-2 mb-0"><?php foreach($gnDsHierarchy['conflicts'] as $ds): ?><li><?= e($ds['dad_number'].' - '.$ds['name_en']) ?></li><?php endforeach; ?></ul><?php endif; ?><?php endif; ?></div><?php endif; ?><?php if($relationships===[]): ?><p class="text-muted mb-0">No other related locations are available for your current access.</p><?php else: ?><ul class="list-group list-group-flush"><?php foreach($relationships as $row): ?><li class="list-group-item px-0"><span class="badge text-bg-light"><?= e(ucwords(strtolower(str_replace('_',' ',$row['relationship_type'])))) ?></span> <?= e($row['parent_number'].' - '.$row['parent_name']) ?> &rarr; <?= e($row['child_number'].' - '.$row['child_name']) ?></li><?php endforeach; ?></ul><?php endif; ?></div></div></div></div>
